<script setup lang="ts">
import {ref,watch} from 'vue';
const props=defineProps<{company:number;book:any}>();
const emit=defineEmits(['navigate']);
const data=ref<any>({}),loading=ref(false),error=ref('');let version=0;
const today=new Date().toLocaleDateString('en-CA');
const amount=(v:any)=>Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
watch(()=>[props.company,props.book],async()=>{const id=++version;data.value={};error.value='';if(!props.book)return;loading.value=true;try{const results=await Promise.all(['profit','receivables','payables'].map(async report=>{const q=new URLSearchParams({company_id:String(props.company),report,from:today.slice(0,7)+'-01',to:today});const r=await fetch('/accounting/api/reports?'+q,{headers:{Accept:'application/json'}});const result=await r.json();if(!r.ok)throw Error(result.message||'Unable to load overview.');return [report,result];}));if(id===version)data.value=Object.fromEntries(results);}catch(e){if(id===version)error.value=(e as Error).message;}finally{if(id===version)loading.value=false;}},{immediate:true});
</script>
<template><section><div class="ac-section-heading"><div><p class="eyebrow">FINANCIAL OVERVIEW</p><h2>Your company at a glance</h2><p class="muted">Outstanding balances as of {{today}}. Income and expenses for this calendar month.</p></div><span class="ac-badge active">{{book?.currency||'Books not configured'}}</span></div><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><p v-if="loading" role="status">Loading financial overview...</p><div v-else-if="!book" class="ac-empty"><h3>Set up your company books</h3><p>Choose your base currency and books start date before recording transactions.</p><button class="button primary" @click="emit('navigate','books')">Open Company books</button></div><template v-else-if="data.profit"><div class="ac-stats ac-overview-stats"><button v-for="card in [{title:'Customers owe you',value:data.receivables.summary.outstanding,section:'receivables'},{title:'You owe suppliers',value:data.payables.summary.outstanding,section:'payables'},{title:'Income this month',value:data.profit.summary.income,section:'profit'},{title:'Expenses this month',value:data.profit.summary.expense,section:'profit'}]" :key="card.title" @click="emit('navigate',card.section)"><small>{{card.title}}</small><strong>{{amount(card.value)}}</strong><span>View details &rarr;</span></button></div><div class="ac-overview-panels"><article class="ac-books-panel"><p class="eyebrow">THIS MONTH</p><h3>Net profit / loss</h3><strong class="ac-profit-number">{{book.currency}} {{amount(data.profit.summary.profit)}}</strong><p class="muted">Calculated from posted income and expense entries.</p><button class="button" @click="emit('navigate','profit')">View Profit and Loss</button></article><article class="ac-books-panel"><p class="eyebrow">QUICK ACTIONS</p><h3>Keep your books moving</h3><div class="ac-quick-actions"><button class="button" @click="emit('navigate','sales')">Sales invoices &rarr;</button><button class="button" @click="emit('navigate','purchases')">Purchase invoices &rarr;</button><button class="button" @click="emit('navigate','journals')">Journal entries &rarr;</button><button class="button" @click="emit('navigate','trial')">Trial Balance &rarr;</button></div></article></div></template></section></template>
